import json
import re

def parse_llm_output(output: str) -> list[dict]:
    """
    Parses the LLM output into a list of dictionaries with "text" and "type" keys.
    Handles cases where the output might be malformed or contain extra text.
    """
    # Remove markdown code fences if present
    cleaned_output = re.sub(r'```json|```', '', output).strip()

    try:
        entities = json.loads(cleaned_output)
        if isinstance(entities, list):
            return entities
        else:
            return []
    except json.JSONDecodeError:
        # If JSON parsing fails, try to extract valid JSON from the text
        json_match = re.search(r'\[.*\]', cleaned_output, re.DOTALL)
        if json_match:
            try:
                entities = json.loads(json_match.group())
                if isinstance(entities, list):
                    return entities
            except json.JSONDecodeError:
                pass
        return []
